import path from 'node:path';
import {
  BUILD_MANIFEST_SCHEMA_VERSION,
  routeFromEntryName,
  writeBuildManifest,
  type BuildManifestChunk,
  type CodeUsageBuildManifest,
} from './build-manifest.js';

export interface CodeUsageMapVitePluginOptions {
  /** Manifest filename inside the Vite output directory. */
  filename?: string;
  /** Optional route ownership mapping: route → entry filename/chunk name. */
  routeEntries?: Record<string, string>;
}

interface ViteResolvedConfigLike {
  root?: string;
  build?: { outDir?: string };
}

interface ViteBundleChunkLike {
  type: 'chunk';
  fileName: string;
  name?: string;
  isEntry?: boolean;
  isDynamicEntry?: boolean;
  imports?: string[];
  dynamicImports?: string[];
  modules?: Record<string, { renderedLength?: number }>;
  viteMetadata?: {
    importedCss?: Iterable<string> | Set<string>;
    importedAssets?: Iterable<string>;
  };
}

interface ViteBundleAssetLike {
  type: 'asset';
  fileName: string;
  name?: string;
  names?: string[];
}

type ViteBundleLike = Record<string, ViteBundleChunkLike | ViteBundleAssetLike>;

interface VitePluginLike {
  name: string;
  apply: 'build';
  enforce?: 'post';
  configResolved(config: ViteResolvedConfigLike): void;
  generateBundle(
    this: { emitFile?: (asset: { type: 'asset'; fileName: string; source: string }) => void },
    options: { dir?: string; file?: string },
    bundle: ViteBundleLike,
  ): void;
  closeBundle(): void;
}

function moduleBytes(modules: Record<string, { renderedLength?: number }> | undefined): BuildManifestChunk['modules'] {
  if (!modules) return [];
  return Object.entries(modules)
    .map(([id, info]) => ({ id, bytes: info.renderedLength ?? 0 }))
    .sort((a, b) => b.bytes - a.bytes)
    .slice(0, 10_000);
}

/**
 * Official Vite build plugin. It writes a Code Usage Map build manifest with
 * entry/initial/lazy chunks, CSS, static/dynamic imports, source module bytes
 * and optional route-to-entry ownership. It does not run analysis inside the
 * build and never ships into the browser bundle.
 */
export function codeUsageMapVitePlugin(options: CodeUsageMapVitePluginOptions = {}): VitePluginLike {
  const filename = options.filename ?? 'code-usage-map.vite.json';
  const routeEntries = options.routeEntries ?? {};
  let root = process.cwd();
  let outputDirectory = '';
  let manifest: CodeUsageBuildManifest | undefined;

  return {
    name: 'code-usage-map:vite',
    apply: 'build',
    enforce: 'post',
    configResolved(config) {
      root = config.root ?? process.cwd();
      outputDirectory = path.resolve(root, config.build?.outDir ?? 'dist');
    },
    generateBundle(options, bundle) {
      outputDirectory = options.dir ? path.resolve(options.dir) : outputDirectory;
      const chunks: BuildManifestChunk[] = [];
      const entryChunks = new Map<string, string>();
      const chunkFileByName = new Map<string, string>();
      const htmlRoutes = new Map<string, string[]>();

      for (const item of Object.values(bundle)) {
        if (item.type !== 'chunk') continue;
        if (item.name) chunkFileByName.set(item.name, item.fileName);
      }

      for (const [bundleKey, item] of Object.entries(bundle)) {
        if (item.type === 'asset' && /\.html?$/i.test(item.fileName)) {
          const route = `/${item.fileName.replace(/\.html?$/i, '').replace(/^index$/, '')}`.replace(/\/+/g, '/');
          const normalized = route === '' ? '/' : route;
          htmlRoutes.set(normalized, [item.fileName]);
          void bundleKey;
        }
      }

      const staticImports = new Map<string, Set<string>>();
      for (const item of Object.values(bundle)) {
        if (item.type !== 'chunk') continue;
        staticImports.set(item.fileName, new Set(item.imports ?? []));
      }
      const initial = new Set<string>();
      const queue: string[] = [];
      for (const item of Object.values(bundle)) {
        if (item.type !== 'chunk') continue;
        if (item.isEntry) {
          initial.add(item.fileName);
          queue.push(item.fileName);
          const derived = routeFromEntryName(item.name ?? item.fileName);
          if (!entryChunks.has(derived)) entryChunks.set(derived, item.fileName);
        }
      }
      while (queue.length > 0) {
        const current = queue.shift();
        if (!current) continue;
        for (const imported of staticImports.get(current) ?? []) {
          if (initial.has(imported)) continue;
          initial.add(imported);
          queue.push(imported);
        }
      }

      for (const item of Object.values(bundle)) {
        if (item.type !== 'chunk') continue;
        const css = item.viteMetadata?.importedCss
          ? [...item.viteMetadata.importedCss]
          : [];
        const routes = [...entryChunks.entries()]
          .filter(([, file]) => file === item.fileName)
          .map(([route]) => route);
        if (routes.length === 0 && item.isEntry) routes.push('/');
        chunks.push({
          file: item.fileName,
          entry: Boolean(item.isEntry),
          initial: initial.has(item.fileName),
          imports: item.imports ?? [],
          dynamicImports: item.dynamicImports ?? [],
          css,
          modules: moduleBytes(item.modules),
          routes,
        });
      }

      const routeManifest = new Map<string, { files: string[]; initial: boolean }>();
      for (const [route, files] of htmlRoutes) routeManifest.set(route, { files, initial: true });
      for (const [route, file] of Object.entries(routeEntries)) {
        const resolved = chunkFileByName.get(file) ?? file;
        const existing = routeManifest.get(route);
        if (existing) existing.files.push(resolved);
        else routeManifest.set(route, { files: [resolved], initial: true });
      }
      for (const [route, file] of entryChunks) {
        const existing = routeManifest.get(route);
        if (existing) existing.files.push(file);
        else routeManifest.set(route, { files: [file], initial: true });
      }
      if (routeManifest.size === 0) routeManifest.set('/', { files: [], initial: true });

      manifest = {
        schemaVersion: BUILD_MANIFEST_SCHEMA_VERSION,
        buildTool: 'vite',
        generator: '@codewithrajat/code-usage-map/vite',
        generatedAt: new Date().toISOString(),
        chunks,
        routes: [...routeManifest.entries()].map(([route, value]) => ({
          route,
          files: [...new Set(value.files)],
          initial: value.initial,
        })),
      };
    },
    closeBundle() {
      if (!manifest) return;
      try {
        writeBuildManifest(outputDirectory, filename, manifest);
      } catch {
        // A plugin must not break the user's build if manifest writing fails.
      }
    },
  };
}
